INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal.kfupm-ias121', 'stk-faisal.kfupm', 'IAS 121', 'doc', '{"docs": [{"id": "stk-dr-aibrahim", "n": "د. عبدالله إبراهيم", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS121 TERM 211\nالتحضير : يحضر بداية الكلاس وما يحاسب على التاخير حتى لو جيت اخر 10 دقائق بيحضرك\nطريقة الشرح : من سلايداته وتعتبر كافية ووافية جدا جدا سواء للكويزات او الميدات او الفاينلات\nالكويزات : سهلة جدا جدا وجميعها اختيار من متعدد عن طريق البلاك بورد ولكن في الحصة\nالميدات : كومن\nالفاينلات : كومن\nالقريد النهائي: A+ ولو فيه أكثر من كذا عطيته ، الدكتور محترم جدا وما يقصر ابدا ويعطيك اكثر مما تستحق وحريص عليك اكثر من نفسك\nالصوت: واضح جدا\nإضافات : انصحك خله اول خياراتك حرفيا من افضل الاشخاص الي درست عندهم سواء من ناحية شرح او كويزات او قريدات ما اقول غير الله يوفقه وين ما راح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533279-ias121", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdullah-ibrahim/68612/88", "user": "Faisal.kfupm", "ts": 1641239552000, "tid": 68612, "pn": 88}}]}', 1641239552000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12191-ias121', 'stk-user12191', 'IAS 121', 'doc', '{"docs": [{"id": "stk-dr-aibrahim", "n": "د. عبدالله إبراهيم", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS121- TERM211\nالتحضير :\nفي بداية الكلاس ينادي بالأسماء. ما يحاسب على التأخير لو جيت في نص الكلاس حضرك. ويقبل الميك اب\nطريقة الشرح :\nشرحه ممتاز جدًا ، يشرح من ملفات الوورد حقته وتعتبر أفضل مصدر تذاكر منه\nالكويزات :\nسهلة جدًا.\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالصوت:\nواضح جدًا\nإضافات:\nالدكتور عبدالله قمة في الشرح والأخلاق ومن أفضل الدكاترة الي يمكن يمرون عليك في مسيرتك الأكاديمية.\nنزل عنده وأنت مغمض.\nالقريد النهائي:\nA+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533365-ias121", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdullah-ibrahim/68612/89", "user": "user12191", "ts": 1641638503000, "tid": 68612, "pn": 89}}]}', 1641638503000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-juha-ias121', 'stk-juha', 'IAS 121', 'doc', '{"docs": [{"id": "stk-dr-aibrahim", "n": "د. عبدالله إبراهيم", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "IAS121 - TERM211\n\nالتحضير : يوميا بالأسماء وما يحاسب على التأخير\nطريقة الشرح : يشرح من نوتته اللي هي أفضل نوتة ويسأل يوميًا عن الدروس السابقة\nالكويزات : سهلة جدا وزود عليها واحد تعويضي\nالمياجر: -\nالفاينلات : -\nالقريد النهائي: A+++++ أفضل دكتور باختصار\nالصوت: واضح\nإضافات : الدكتور غالبا يعامل الطلاب على انهم فاهمين ومتأسسين كويس لذلك بعض الطلاب اللي عندهم صعوبات يتعبون معاه لأن شرحه سريع نوعا ما رغم انه يكرر نقاطه كثير، لكن الميزة اللي فيه انه ما يرد سؤال للطالب مهما كان\n\nلا تفكر مرتين قبل ما تسجل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533543-ias121", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdullah-ibrahim/68612/90", "user": "juha", "ts": 1642922142000, "tid": 68612, "pn": 90}}]}', 1642922142000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-ias121', 'stk-guest', 'IAS 121', 'doc', '{"docs": [{"id": "stk-dr-jurayan", "n": "د. خالد الجريان", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "201-ias 121\n\nالتحضير : يحضر بالتيمز مايدقق كثير في هذا الامر\n\nالشرح: بكل صراحة الاغلب يمدح شرحه لكنه م عجبني الدكتور يسترسل كثييييييييييير يعني يبدا الكلاس ١٠ دقايق ويعطيك سالفة ٢٠ دقيقه قد يعجب البعض لكن انا حاولت اركز معه م قدرت\n\nالكويزات: سهلة وبيد الجميع\n\nاضافات : نفس م قلت فوق الدكتور يحب يسولف كثير + م يدري عن الوقت الكلاس يخلص و٥٠ لو م احد يقوله عادي يكمل الى بداية الكلاس الي بعده … كل كلاس ياخذ له ٥-٧ دقائق\nالكويزات تكون في وقت خارج الكلاس وصارت مشكلة على هذا الموضوع يبقى كل السكاشن تختبر في نفس الوقت وكل م تحدد وقت طلع فيه تعارض عند اشخاص ويأجل ويأجل كل كويز يتغير موعده ٤-٥ مرات بالراحة\nفي الاخير كان باقي لي درجتين على القريد الي بعده وزادني\n\nالقريد النهائي B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527724-ias121", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-jurayan/172426/34", "user": "Guest", "ts": 1610182084000, "tid": 172426, "pn": 34}}]}', 1610182084000, 1794312708, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
